import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"pages/overview/features.md","filePath":"pages/overview/features.md"}`),a={name:`pages/overview/features.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h1><ul><li><p><strong>Database-agnostic with broad driver support</strong>. The exporter supports a wide range of databases including PostgreSQL, MySQL, Microsoft SQL Server, and more.</p></li><li><p><strong>Scrape-synchronous collection with optional caching</strong>. Metrics are collected on each Prometheus <code>/metrics</code> poll, which avoids the jitter, duplicate points and unscraped data of fixed-interval exporters. Minimal interval can be set per collector to serve cached results when scrapes are more frequent.</p></li><li><p><strong>Staggered cache warmup</strong>. To prevent thundering herd effect on the database, the cache warmup is staggered on startup if configured.</p></li><li><p><strong>Fully configuration-driven metrics</strong>. Metrics and the SQL queries behind them are defined in YAML. Queries are grouped into reusable collectors.</p></li><li><p><strong>Flexible metric mapping</strong>. Each metric supports a flexible mapping from query results to Prometheus metrics to enrich the data with labels and values. The exporter can be configured to skip empty rows or rows with <code>NULL</code> label values.</p></li><li><p><strong>Multi-target (jobs) mode</strong>. Single exporter instance can monitor many databases through a jobs list. Each job has named targets, shared labels and its own collector set.</p></li><li><p><strong>Selective job scraping</strong>. The <code>jobs[]</code> query parameter lets Prometheus scrape particular jobs. This allows for more flexible scraping strategies.</p></li><li><p><strong>Secret manager integration</strong> Connection string can reference a secret instead of holding static credentials for the following secret managers:</p><ul><li>Kubernetes Secrets</li><li>AWS Secrets Manager</li><li>Google Cloud Secrets Manager</li><li>Hashicorp Vault</li></ul></li><li><p><strong>Secured HTTP/S endpoint</strong>. Use TLS certificates and basic authentication to secure the endpoint.</p></li><li><p><strong>Request rate limiting</strong>. Limit the number of requests per second to avoid overload and protect the exporter from DoS attacks.</p></li><li><p><strong>Live reload of configuration without restart</strong>. Reload the configuration file on SIGHUP signal or via HTTP endpoint without restarting the exporter.</p></li><li><p><strong>Automatic metrics</strong>. Extra metrics for configured targets are collected automatically, including scrape duration, scrape errors, etc.</p></li><li><p><strong>Builtin validation and config check</strong>.</p></li></ul>`,2)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};